void move_snake(Snake *snake, int direction) {
    Point *new_tail = (Point *)malloc(sizeof(Point));
    *new_tail = snake->body[snake->length - 1];

    for (int I = snake->length - 2; I >= 0; i--) {
        snake->body[i + 1] = snake->body[i];
    }

    switch (direction) {
        case 0:
            snake->body[0].x--;
            break;
        case 1:
            snake->body[0].x++;
            break;
        case 2:
            snake->body[0].y--;
            break;
