        SDL_RenderCopy(renderer, snake_head, NULL, &snake_head_rect);

        for (int I = 1; I < snake.length; i++) {
            SDL_Rect snake_body_rect = {
                .x = snake.body[i].x * 20,
                .y = snake.body[i].y * 20,
                .w = 20,
                .h = 20
            };

            SDL_RenderCopy(renderer, snake_body, NULL, &snake_body_rect);
        }

        SDL_RenderCopy(renderer, food, NULL, &food_rect);

        SDL_RenderPresent(renderer);

        // Check for collision with food
        if (snake.body[0].x == food.x && snake.body[0].y == food.y) {
            snake.length++;
            food = create_food(WIDTH / 20, HEIGHT / 20);
