Voici un programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string fileName;
    std::string searchWord;
    int count = 0;

    // Prompt user for file name and search word
    std::cout << "Enter file name: ";
    std::cin >> fileName;

    std::cout << "Enter search word: ";
    std::cin >> searchWord;

    // Open file and read line by line
    std::ifstream file(fileName);
    if (!file) {
        std::cerr << "Error opening file: " << fileName << std::endl;
        return 1;
    }

    std::string line;
    while (getline(file, line)) {
        // Convert line to lowercase to make search case-insensitive
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of search word
        size_t pos = 0;
        while ((pos = line.find(searchWord, pos)) != std::string::npos) {
            count++;
            pos += searchWord.length();
        }
    }

    file.close();

    // Output results
    std::cout << "Search word: " << searchWord << std::endl;
    std::cout << "File name: " << fileName << std::endl;
    std::cout << "Number of occurrences: " << count << std::endl;

    return 0;
}
