```python
def longest_common_subsequence(str1, str2):
    m = len(str1)
    n = len(str2)

    # Create a 2D array to store the LCS lengths
    lcs_table = [[0] * n for _ in range(m)]

    # Fill the table using dynamic programming
    for I in range(m):
        for j in range(n):
            if I == 0 or j == 0:
                lcs_table[i][j] = 0
            elif str1[i] == str2[j]:
                lcs_table[i][j] = lcs_table[i-1][j-1] + 1
            else:
                lcs_table[i][j] = max(lcs_table[i-1][j], lcs_table[i][j-1])

    # Find the longest common subsequence by following the backtracking path
    def backtrack(i, j, sequence):
        if I == 0 or j == 0:
            return sequence
        elif str1[i] == str2[j]:
            sequence.append(str1[i])
            return backtrack(i-1, j-1, sequence)
        else:
            if lcs_table[i-1][j] > lcs_table[i][j-1]:
                return backtrack(i-1, j, sequence)
            else:
                return backtrack(i, j-1, sequence)

    # Initialize an empty sequence to store the LCS
    lcs = []

    # Call the backtrack function to fill the LCS
    lcs = backtrack(m-1, n-1, lcs)

    # Return the LCS and its length
    return lcs, len(lcs)
